import {MarkdownWorkerRuntime} from '../../../src/core/platform/web/markdownWorkerRuntime';
import {DocumentSessions} from '../../../src/application/sessions/documentSessions';
import {MemoryPreviewCache} from '../../../src/application/previewCache/memoryPreviewCache';
import {createPreviewSubmission} from '../../../src/application/tasks/previewIdentity';
import {estimatedBytes} from '../../../src/application/tasks/budget';
import {DEFAULT_THEME} from '../../../src/core/model/document';
const output=document.querySelector('[data-dual-state]'),sessions=new DocumentSessions(),cache=new MemoryPreviewCache();
const source=Array.from({length:96},(_,i)=>['## 节 '+i+' 🧪','','内容 $x^2$ 与纯解析映射。第'+i+'段文字。','','```ts','const n='+i+';','```',''].join('\r\n')).join('\r\n');
for(const id of ['A','B','C','D'])sessions.open({schemaVersion:1,id,revision:1,markdown:'# '+id+'\r\n\r\n'+source,meta:{title:id,createdAt:'2026-10-25',updatedAt:'2026-10-25'},theme:DEFAULT_THEME,options:{syntaxProfile:'commonmark-gfm-v1',mathMode:'mathml'}});
function pageHeap(){const p=performance as Performance&{memory?:{usedJSHeapSize:number;totalJSHeapSize:number}};return p.memory?{usedJSHeapSize:p.memory.usedJSHeapSize,totalJSHeapSize:p.memory.totalJSHeapSize}:null}
const memoryTrend=[{stage:'beforeWorkers',pageHeapReported:pageHeap(),cacheBytes:cache.stats().estimatedBytes,liveRoleInstances:0,resources:0}];
const created=performance.now(),runtime=new MarkdownWorkerRuntime(sessions,{now:()=>performance.now(),schedule:(ms,callback)=>{const id=setTimeout(callback,ms);return()=>clearTimeout(id)}},()=>1,cache),constructionMs=performance.now()-created,scheduler=runtime.coordinator.scheduler;
function recordMemory(stage:string){const snapshot=runtime.snapshot();memoryTrend.push({stage,pageHeapReported:pageHeap(),cacheBytes:cache.stats().estimatedBytes,liveRoleInstances:snapshot.roles.filter(r=>!r.stopped).length,resources:snapshot.scheduler.resources.length})}
recordMemory('afterConstruction');
let peakForeground=0,peakBackground=0,peakActive=0,timerDelayMs=0,lastTick=performance.now();
const timer=setInterval(()=>{const now=performance.now();timerDelayMs=Math.max(timerDelayMs,now-lastTick-10);lastTick=now},10);
function sample(){const snapshot=scheduler.snapshot(),active=snapshot.queue.active;peakForeground=Math.max(peakForeground,active.filter(a=>a.role==='foreground').length);peakBackground=Math.max(peakBackground,active.filter(a=>a.role==='background').length);peakActive=Math.max(peakActive,active.length);if(peakForeground>1||peakBackground>1)throw new Error('Role concurrency exceeded');return snapshot}
function accepted(result:{status:string;taskId?:string}|undefined):string{if(result?.status!=='accepted'||!result.taskId)throw new Error('Expected admission: '+JSON.stringify(result));return result.taskId}
function background(id:string){return accepted(scheduler.enqueuePreview(createPreviewSubmission({taskId:'probe',document:sessions.read(id).document,previewKind:'preview.flow',role:'background',renderConfigVersion:1})))}
function edit(id:string,label:string){const doc=sessions.read(id).document;sessions.update({...doc,revision:doc.revision+1,markdown:doc.markdown+'\r\n\r\n'+label})}
async function settled(ids:string[],allowFailure=false){const begin=performance.now(),times:Record<string,number>={};for(;;){sample();for(const id of ids){const state=scheduler.status(id)?.state;if((state==='completed'||allowFailure&&state==='failed')&&times[id]===undefined)times[id]=performance.now()-begin;else if(state==='failed'&&!allowFailure)throw new Error(scheduler.status(id)?.reason)}if(ids.every(id=>times[id]!==undefined))return times;if(performance.now()-begin>20000)throw new Error('Task did not settle');await new Promise(resolve=>setTimeout(resolve,5))}}
function artifactTask(id:string){const ref=sessions.read(id).previewReferences['preview.flow'];if(!ref)throw new Error('Missing cached document '+id);const artifact=cache.resolve(ref)?.artifact;if(!artifact)throw new Error('Expired cached document '+id);return artifact.artifactId}
function generation(role:'foreground'|'background'){return runtime.snapshot().roles.find(r=>r.role===role)!.generation!}
async function run(){
 if(new URL(location.href).searchParams.has('fault')){
  const a=accepted(runtime.activate('A').foreground),c=background('C');sample();await settled([a,c],true);
  const failed=[{role:'foreground' as const,id:a,doc:'A'},{role:'background' as const,id:c,doc:'C'}].filter(item=>scheduler.status(item.id)?.state==='failed');if(!failed.length)throw new Error('Expected native module-load failure');
  const recovered=[];for(const item of failed){const fresh=item.role==='foreground'?accepted(runtime.activate('A').foreground):background('C');await settled([fresh]);recovered.push({role:item.role,failedTask:item.id,failedState:scheduler.status(item.id)?.state,newTask:fresh,artifactTask:artifactTask(item.doc),generation:generation(item.role)})}
  return {fault:true,recovered,peakForeground,peakBackground,peakActive};
 }
 const coldStart=performance.now(),a=accepted(runtime.activate('A').foreground),c=background('C');sample();const cold=await settled([a,c]),coldWallMs=performance.now()-coldStart;recordMemory('afterCold');
 const warm=[];for(let round=0;round<3;round++){edit('A','warm '+round);edit('C','warm '+round);const begin=performance.now(),front=accepted(runtime.activate('A').foreground),back=background('C');sample();const times=await settled([front,back]);warm.push({round,foregroundMs:times[front],backgroundMs:times[back],wallMs:performance.now()-begin});recordMemory('warm-'+round)}
 edit('C','fifo');const fifoC=background('C'),fifoB=background('B'),fifoD=background('D');edit('B','latest pending');const newestB=background('B');await settled([fifoC,newestB,fifoD]);const fifo=scheduler.snapshot().history.filter(h=>h.state==='completed'&&[fifoC,newestB,fifoD].includes(h.id)).map(h=>h.id===fifoC?'C':h.id===newestB?'B':'D');
 const beforeCancel={foreground:generation('foreground'),background:generation('background')};edit('A','cancel outgoing');edit('C','unrelated C');edit('B','incoming B');const oldA=accepted(runtime.activate('A').foreground),unrelatedC=background('C');sample();const switched=runtime.activate('B'),newB=accepted(switched.foreground),newA=accepted(switched.background);await settled([newA,newB,unrelatedC]);
 const cancel={oldState:scheduler.status(oldA)?.state,foregroundRebuilt:generation('foreground')>beforeCancel.foreground,unrelatedBackgroundPreserved:generation('background')===beforeCancel.background,oldTask:oldA,newArtifactTask:artifactTask('A'),newTask:newA};
 const beforePromotion={foreground:generation('foreground'),background:generation('background')};edit('A','promote unfinished');edit('B','leave unfinished');const oldB=accepted(runtime.activate('B').foreground),oldBackA=background('A');sample();const promoted=runtime.activate('A'),freshA=accepted(promoted.foreground),freshB=accepted(promoted.background);await settled([freshA,freshB]);
 const promotion={oldForegroundState:scheduler.status(oldB)?.state,oldBackgroundState:scheduler.status(oldBackA)?.state,foregroundRebuilt:generation('foreground')>beforePromotion.foreground,backgroundRebuilt:generation('background')>beforePromotion.background,foregroundArtifactTask:artifactTask('A'),foregroundTask:freshA,backgroundArtifactTask:artifactTask('B'),backgroundTask:freshB};
 const historyBefore=scheduler.snapshot().history.length,reference=runtime.coordinator.currentPreviewReference()?.id,hit=runtime.activate('A'),cacheHitNoGeneration=hit.foreground===undefined&&hit.cacheReference===reference&&scheduler.snapshot().history.length===historyBefore;
 recordMemory('afterSwitches');
 const ref=sessions.read('A').previewReferences['preview.flow']!,value=cache.resolve(ref)!;
 return {fault:false,constructionMs,cold:{foregroundMs:cold[a],backgroundMs:cold[c],wallMs:coldWallMs,includesFirstModuleLoad:true},warm,peakForeground,peakBackground,peakActive,timerDelayMs,inputUtf8Bytes:new TextEncoder().encode(sessions.read('A').document.markdown).byteLength,inputSnapshotBytes:estimatedBytes(sessions.read('A').document),artifactSerializedBytes:estimatedBytes(value.artifact),cacheBytes:cache.stats().estimatedBytes,pageHeapReported:pageHeap(),workerPhysicalHeapBytes:null,fifo,replacedPendingState:scheduler.status(fifoB)?.state,cancel,promotion,cacheHitNoGeneration,finalQueue:scheduler.snapshot().queue,roles:runtime.snapshot().roles,userAgent:navigator.userAgent,hardwareConcurrency:navigator.hardwareConcurrency,secure:isSecureContext,uuid:typeof crypto.randomUUID,subtle:typeof crypto.subtle};
}
void (async()=>{try{const report=await run();runtime.dispose();await Promise.resolve();await Promise.resolve();const cleanup=scheduler.snapshot();recordMemory('afterDispose');if(output){output.textContent=JSON.stringify({...report,memoryTrend,activePinAfterDispose:cache.stats().activeReferenceId??null,disposed:runtime.snapshot().disposed,retainedResources:cleanup.resources.length,remainingPending:cleanup.queue.pending.foreground.length+cleanup.queue.pending.background.length});output.setAttribute('data-dual-state','ready')}}catch(error){runtime.dispose();if(output){output.textContent=String(error);output.setAttribute('data-dual-state','error')}}finally{clearInterval(timer)}})();
